A = [
dict(n=44, slug="prompt-caching", title="Why Do Repeated Prompts Get Cheaper?", topic="Prompt caching",
buzz='"Prompt caching: up to 90% off." AI providers advertise it. Why would asking the same thing again cost less?',
hw='A teacher reads the same 50-page rulebook aloud before every exam question. Wasteful. Better: read it once, keep notes, and for each new question, only read the question.\n\nThat\'s the hello world: **prompt caching** saves the work done on the repeated start of a prompt and reuses it for the next request.',
step='Many apps send the same long beginning every time: instructions, policies, a document. The provider stores the processed version of that beginning (the KV cache, write-up 43) for a short while. If your next request starts the same way, it skips that work and charges much less for those tokens.\n\nIt only helps if the repeated part comes first and is exactly the same. Change one character at the start and the saving is lost.',
met='"Cached input" lines on AI bills. Faster replies in chat apps that reuse long instructions.',
name='**Prompt caching**, also called **context caching**.',
words=[("Cache hit","the repeated start was found and reused."),("Prefix","the beginning part of a prompt."),("Cache lifetime","how long the saved work is kept.")],
notit='It\'s not caching answers. The AI still writes a fresh answer; only the reading of the repeated part is saved. (Cost strategies are covered in Series 8.)',
take=["Put fixed instructions and documents first, the changing question last.","Keep the fixed part exactly identical between requests.","Check your bill for cached-token lines to see if it's working."],
close="Read the rulebook once. Keep the notes.",
q="Does your AI app send the same long instructions every time?",
scene='Reading the same 50-page rulebook\nbefore every single question.',
hook="Prompt caching reads it once and reuses the notes.",
extra="Same start, much cheaper."),

dict(n=47, slug="tpu", title="What Is a TPU, and Why Did Google Build One?", topic="TPU",
buzz='"Trained on TPUs." Google\'s models mention them. They\'re a different kind of AI chip from the GPUs in every headline.',
hw='A Swiss army knife does many jobs. A bread knife does one job, cutting bread, and does it very well.\n\nGPUs (write-up 46) are the Swiss army knife: built for graphics, great for AI too. That\'s the hello world: a **TPU** is the bread knife, a chip Google designed only for the maths AI needs.',
step='AI is mostly multiplying big grids of numbers. TPUs (tensor processing units) are built around exactly that, packed into large connected groups for training and serving big models.\n\nGoogle first used them in its own data centres around 2015 and now rents them through Google Cloud. Other companies build similar custom chips, such as AWS\'s Trainium and Inferentia.',
met='Google Search, Translate and Gemini run on TPUs. You meet them indirectly every time you use those.',
name='The **TPU** (tensor processing unit).',
words=[("TPU","Google's custom chip for AI maths."),("Tensor","a grid of numbers, the basic unit of AI maths."),("Custom silicon","chips designed for one company's needs.")],
notit='A TPU isn\'t something you buy for your desk. It\'s rented in the cloud. And it isn\'t automatically faster than a GPU for every job.',
take=["Know that GPUs aren't the only AI chips.","Compare cost per task, not chip names.","Expect more custom AI chips from cloud providers."],
close="Not a Swiss army knife. A bread knife for AI.",
q="Did you know Google built its own AI chips?",
scene='A Swiss army knife does everything.\nA bread knife does one job, very well.',
hook="A TPU is Google's bread knife for AI maths.",
extra="Built for one job: the sums AI needs."),

dict(n=48, slug="npu", title="What's the AI Chip Inside Your New Laptop?", topic="NPU",
buzz='"AI PC." "Built-in NPU." New laptops and phones advertise a chip for AI. What does it do that the old ones didn\'t?',
hw='Your laptop has a main brain (CPU) for everything and a graphics chip for games. Now it also has a small, energy-saving helper for one kind of job: running AI features.\n\nThat\'s the hello world: an **NPU** (neural processing unit) is a low-power chip in your device built to run AI quickly without draining the battery.',
step='Running AI on the main chip is slow and drains power. An NPU handles the number-crunching of neural networks (write-up 5) efficiently, so features like background blur, live captions or on-device assistants (write-up 50) can run constantly.\n\nNPUs are small compared with data-centre chips, so they run small models (write-up 49), not the biggest ones.',
met='"Copilot+ PC" and "AI PC" laptops, and phone chips with a "neural engine". Video-call background blur and live captions.',
name='The **NPU** (neural processing unit), sometimes called a **neural engine**.',
words=[("NPU","a power-efficient chip for running AI on devices."),("TOPS","trillions of operations per second, a common NPU speed figure."),("On-device AI","AI running locally (write-up 50).")],
notit='An NPU won\'t run the largest AI models; those still need the cloud. And a big TOPS number doesn\'t guarantee useful features.',
take=["Check which AI features actually use the NPU before paying extra.","Prefer devices where AI features work offline if privacy matters.","Don't buy on TOPS numbers alone."],
close="A small, efficient helper just for AI.",
q="Does your laptop or phone have an NPU?",
scene='Main brain for everything. Graphics chip for games.\nAnd now, a small chip just for AI.',
hook="That's the NPU: low-power AI, right on your device.",
extra="It runs small models, not the giant ones."),

dict(n=49, slug="small-language-model", title="Can a Small AI Be Good Enough?", topic="Small language model",
buzz='"Small language models." After years of "bigger is better", small models are the new trend. Small how, and good at what?',
hw='A library has every book. A pocket dictionary is small, but for most quick look-ups, it\'s all you need, and it fits in your pocket.\n\nThat\'s the hello world: a **small language model (SLM)** is a compact model, a few billion knobs (write-up 26) instead of hundreds of billions, good enough for many everyday tasks.',
step='Small models are made capable with high-quality training data and distillation from bigger models (write-up 34), then shrunk further with quantization (write-up 41).\n\nThey\'re cheaper, faster and can run on a laptop or phone. The trade-off: less knowledge and weaker reasoning on hard problems. Many systems route easy questions to a small model and hard ones to a big model (write-up 104).',
met='Phone keyboards, offline assistants, and the "mini" or "small" versions of popular models.',
name='A **small language model (SLM)**.',
words=[("SLM","a language model small enough to run cheaply or locally."),("Model size","number of parameters, like 3B or 8B."),("Routing","sending each request to the right-sized model.")],
notit='Small doesn\'t mean bad. For narrow, well-defined tasks, a small model can match a big one at a fraction of the cost.',
take=["Try a small model first for simple, repetitive tasks.","Test it on your hardest real cases.","Use big models only where small ones fall short."],
close="A pocket dictionary for most look-ups.",
q="Have you tried a small model for an everyday task?",
scene='The library has every book.\nThe pocket dictionary fits in your hand.',
hook="A small language model is the pocket dictionary.",
extra="Good enough for most quick jobs, at a fraction of the cost."),

dict(n=50, slug="on-device-ai", title="Can an AI Live on Your Phone?", topic="On-device AI",
buzz='"On-device AI." "Works offline." Phone makers now promise AI that never leaves your phone. How?',
hw='Asking a question to the cloud is like phoning a friend in another city: it needs a connection, takes a moment, and your question travels.\n\nThat\'s the hello world: **on-device AI** runs the model on your phone or laptop itself, so it works offline, answers instantly and your data can stay with you.',
step='It\'s made possible by small models (write-up 49), quantization (write-up 41) and NPU chips (write-up 48) in modern devices.\n\nBecause devices are limited, many features are hybrid: easy tasks run on the device, harder ones are sent to the cloud. Good products tell you which is which.',
met='Offline voice typing, photo clean-up, notification summaries and live captions that work in aeroplane mode.',
name='**On-device AI**, also **edge AI** or **local AI**.',
words=[("On-device","running on your own device."),("Edge AI","AI running close to where data is created."),("Hybrid AI","device for easy tasks, cloud for hard ones.")],
notit='On-device doesn\'t always mean private. Check whether a feature quietly sends harder requests to the cloud.',
take=["Use on-device AI for quick, private, everyday tasks.","Check which features stay on the device.","Expect hybrid: device first, cloud when needed."],
close="No call to another city needed.",
q="Which AI feature on your phone works in aeroplane mode?",
scene='Asking the cloud is phoning a friend in another city.\nWhat if the friend lived in your phone?',
hook="That's on-device AI: answers without the call.",
extra="Offline, instant, and your data can stay with you."),

dict(n=51, slug="latency", title="Why Does the AI Take So Long to Answer?", topic="Latency",
buzz='"We need lower latency." Engineers say it when users complain AI is slow. What exactly is being measured?',
hw='You ask a question in a shop. The time until the shopkeeper finishes answering is what you feel as "slow" or "fast".\n\nThat\'s the hello world: **latency** is the delay between asking and getting the answer.',
step='For AI, latency adds up from many steps: sending your message, looking up documents (write-up 53), the model reading the prompt, the model writing the answer token by token (write-up 11), and any tool calls in between.\n\nLong prompts, big models, reasoning (write-up 71) and agents doing many steps all add delay. Smaller models, caching (write-up 44), streaming (write-up 25) and doing steps in parallel all cut it.',
met='The spinner before a chatbot replies. Voice assistants that feel awkward because of the pause.',
name='**Latency**.',
words=[("Latency","the delay between request and response."),("Time to first token","the delay before the first word (write-up 52)."),("Throughput","how many requests a system can handle.")],
notit='Latency isn\'t only about the model. Slow document search, network hops and extra steps often add more delay than the AI itself. (Performance in production is covered in #JustAddRAG 11.)',
take=["Measure each step, not just the total.","Stream answers so users see progress.","Use smaller models for steps that don't need big ones."],
close="The wait between asking and knowing.",
q="How long will you wait for an AI answer before giving up?",
scene='You ask a question.\nYou wait. And wait.',
hook="That wait is latency: every step between asking and answering.",
extra="It's not only the model. Measure every step."),

dict(n=52, slug="time-to-first-token", title="Why Does the First Word Matter Most?", topic="Time to first token",
buzz='"TTFT." AI teams obsess over it. It\'s the speed number users actually feel.',
hw='At a restaurant, a waiter who brings bread and water in one minute feels fast, even if the meal takes 20. A waiter who brings nothing for 15 minutes feels slow, even if everything arrives at once.\n\nThat\'s the hello world: **time to first token** is how long until the AI\'s first word appears.',
step='With streaming (write-up 25), people start reading as soon as the first word arrives. So the wait before that first word decides whether an AI feels fast.\n\nIt grows with long prompts, document look-ups before answering, reasoning time (write-up 71) and busy servers. Prompt caching (write-up 44) and smaller prompts shrink it.',
met='Chatbots that start typing almost instantly, versus ones that think for 10 seconds first.',
name='**Time to first token (TTFT)**.',
words=[("TTFT","the delay before the first word appears."),("Tokens per second","how fast words keep arriving after that."),("Perceived speed","how fast it feels to the user.")],
notit='A fast first word doesn\'t mean a fast full answer. Measure both: the first word and the speed of the rest.',
take=["Track time to first word as your main speed measure.","Show something quickly: a first word, a status, or progress.","Trim long prompts and cache the fixed parts."],
close="Bring the bread first.",
q="Does a fast first word make an AI feel faster to you?",
scene='Bread and water in one minute: fast service.\nNothing for 15 minutes: slow, even if it all arrives at once.',
hook="Time to first token is the AI's bread basket.",
extra="It's the speed users actually feel."),
]
